fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n {
        // Invariants (informally maintained):
        // 0 <= i <= n
        // result.len() == i
        // all elements in result are 1
        result.push(1);
        i += 1;
    }

    result
}